static char *str_add(const char *a, const char *b) {
    size_t la = strlen(a), lb = strlen(b);
    size_t lm = la > lb ? la : lb;
    char *r = malloc(lm + 2);
    if (!r) {
        fprintf(stderr, "out of memory\n");
        exit(1);
    }
    r[lm + 1] = '\0';
    int carry = 0;
    for (size_t i = 0; i < lm; i++) {
        int da = i < la ? a[la - 1 - i] - '0' : 0;
        int db = i < lb ? b[lb - 1 - i] - '0' : 0;
        int s = da + db + carry;
        r[lm - i] = (char)('0' + (s % 10));
        carry = s / 10;
    }
    if (carry) {
        r[0] = (char)('0' + carry);
        return r;
    }
    memmove(r, r + 1, lm + 1);
    return r;
}

